import json, math
from pathlib import Path

data=json.loads(Path('/root/data.json').read_text())
rep=json.loads(Path('/root/report.json').read_text())
Q=data['vehicle_capacity']; pen=data['penalty_weight']
stations=data['stations']
ids=[int(s['id']) for s in stations]
id_to_idx={sid:i for i,sid in enumerate(ids)}
locs=[{'lat':float(s['latitude']),'lon':float(s['longitude'])} for s in stations]
dep={'lat':float(data['depot']['latitude']),'lon':float(data['depot']['longitude'])}

def gc(a,b,r=3960.0):
 deg=math.pi/180
 phi1=(90-a['lat'])*deg; phi2=(90-b['lat'])*deg
 th1=a['lon']*deg; th2=b['lon']*deg
 cos_arc=math.sin(phi1)*math.sin(phi2)*math.cos(th1-th2)+math.cos(phi1)*math.cos(phi2)
 return math.acos(max(-1,min(1,cos_arc)))*r

def node_loc(node):
 if node in ('depot_start','depot_end'):
  return dep
 return locs[id_to_idx[int(node)]]

def dist(i,j):
 return gc(node_loc(i),node_loc(j))

travel=0.0
for v in rep['vehicles']:
 for i,j in zip(v['route'],v['route'][1:]):
  travel+=dist(i,j)

print('travel recomputed',travel)
print('travel reported',rep['summary']['travel_distance_miles'])

station_pu={sid:0.0 for sid in ids}
station_do={sid:0.0 for sid in ids}
for v in rep['vehicles']:
 for st in v['stops']:
  station_pu[st['station_id']]+=st['bikes_picked_up']
  station_do[st['station_id']]+=st['bikes_dropped_off']

unmet=0.0
for s in stations:
 sid=s['id']
 net=station_pu[sid]-station_do[sid]
 unmet+=abs(s['net_rebalancing_target']-net)
print('unmet recomputed',unmet)
print('unmet reported',rep['summary']['total_unmet_rebalancing_amount'])
print('obj recomputed',travel+pen*unmet)
print('obj reported',rep['summary']['objective'])
